import { NextResponse } from 'next/server';

let goals = [
    { id: 1, title: "Primeira Venda", description: "Realize sua primeira emissão", rewardXp: 500, icon: "Target", type: "Venda" },
    { id: 2, title: "Mestre do A1", description: "Venda 10 certificados A1 em um mês", rewardXp: 2000, icon: "Zap", type: "Venda" },
    { id: 3, title: "Fidelidade", description: "5 dias seguidos de acessos", rewardXp: 300, icon: "Flame", type: "Acesso" },
];

export async function GET() {
    return NextResponse.json(goals);
}

export async function POST(request: Request) {
    const data = await request.json();
    const newGoal = { ...data, id: Date.now() };
    goals.push(newGoal);
    return NextResponse.json(newGoal, { status: 201 });
}
